1	#!/usr/bin/env node
2	/**
3	 * 서버 내 멀티 Claude 에이전트 통신 시스템
4	 * 같은 서버에서 여러 Claude 인스턴스가 메시지 교환
5	 */
6	
7	const Anthropic = require("@anthropic-ai/sdk");
8	const EventEmitter = require("events");
9	
10	// ============= 메시지 버스 (IPC) =============
11	class MessageBus extends EventEmitter {
12	  constructor() {
13	    super();
14	    this.agents = new Map();
15	    this.messageLog = [];
16	  }
17	
18	  register(agentId, agent) {
19	    this.agents.set(agentId, agent);
20	    console.log(`✅ 에이전트 등록: ${agentId}`);
21	  }
22	
23	  async send(fromId, toId, message) {
24	    const envelope = {
25	      timestamp: new Date().toISOString(),
26	      from: fromId,
27	      to: toId,
28	      message,
29	      id: `msg_${Date.now()}_${Math.random().toString(36).slice(2)}`
30	    };
31	
32	    this.messageLog.push(envelope);
33	    console.log(`\n📨 [${fromId}] → [${toId}]`);
34	    console.log(`   메시지: ${message.substring(0, 100)}...`);
35	
36	    // 수신자에게 메시지 전달
37	    const recipient = this.agents.get(toId);
38	    if (recipient) {
39	      await recipient.receiveMessage(envelope);
40	    } else {
41	      console.warn(`⚠️  수신자 ${toId}를 찾을 수 없습니다`);
42	    }
43	
44	    return envelope;
45	  }
46	
47	  getLog() {
48	    return this.messageLog;
49	  }
50	}
51	
52	// ============= Claude 에이전트 =============
53	class ClaudeAgent {
54	  constructor(id, role, bus) {
55	    this.id = id;
56	    this.role = role;
57	    this.bus = bus;
58	    this.client = new Anthropic();
59	    this.inbox = [];
60	    this.messageHistory = [];
61	
62	    // 역할별 시스템 프롬프트
63	    this.systemPrompts = {
64	      researcher: `당신은 연구원입니다. 주어진 주제에 대해 깊이 있게 분석합니다.
65	다른 에이전트의 피드백을 수집하고 종합합니다.`,
66	      critic: `당신은 비평가입니다. 제시된 아이디어를 비판적으로 검토합니다.
67	논리적 결함과 개선점을 지적합니다.`,
68	      synthesizer: `당신은 종합가입니다. 여러 의견을 통합하여 최종 결론을 도출합니다.
69	모든 관점을 존중하면서 균형잡힌 결론을 만듭니다.`
70	    };
71	
72	    this.bus.register(id, this);
73	  }
74	
75	  async receiveMessage(envelope) {
76	    this.inbox.push(envelope);
77	    console.log(`\n💬 [${this.id}] 메시지 수신 완료`);
78	  }
79	
80	  async processInbox() {
81	    if (this.inbox.length === 0) {
82	      console.log(`[${this.id}] 받은 메시지 없음`);
83	      return null;
84	    }
85	
86	    const message = this.inbox.shift();
87	    console.log(`\n🔄 [${this.id}] 메시지 처리 중...`);
88	
89	    // Claude가 응답 생성
90	    const systemPrompt = this.systemPrompts[this.role] || this.systemPrompts.researcher;
91	
92	    const response = await this.client.messages.create({
93	      model: "claude-opus-4-6",
94	      max_tokens: 500,
95	      system: systemPrompt,
96	      messages: [
97	        {
98	          role: "user",
99	          content: `다른 에이전트(${message.from})로부터 다음 메시지를 받았습니다:\n\n"${message.message}"\n\n이에 대해 당신의 관점을 간단히 (2-3문장) 제시해주세요.`
100	        }
101	      ]
102	    });
103	
104	    const reply = response.content[0].text;
105	    this.messageHistory.push({
106	      received: message,
107	      response: reply
108	    });
109	
110	    return reply;
111	  }
112	
113	  async sendMessage(targetId, message) {
114	    await this.bus.send(this.id, targetId, message);
115	  }
116	
117	  getHistory() {
118	    return this.messageHistory;
119	  }
120	}
