122	// ============= 협업 워크플로우 =============
123	async function collaborativeWorkflow() {
124	  console.log(`\n${"=".repeat(70)}`);
125	  console.log(`🤝 서버 내 멀티 Claude 협업 시스템`);
126	  console.log(`${"=".repeat(70)}\n`);
127	
128	  // 메시지 버스 생성
129	  const bus = new MessageBus();
130	
131	  // 3개 에이전트 생성
132	  const researcher = new ClaudeAgent("researcher", "researcher", bus);
133	  const critic = new ClaudeAgent("critic", "critic", bus);
134	  const synthesizer = new ClaudeAgent("synthesizer", "synthesizer", bus);
135	
136	  const topic = "AI의 미래는 밝을까?";
137	  console.log(`\n📌 주제: ${topic}\n`);
138	
139	  // Step 1: 연구원이 초기 관점 제시
140	  console.log(`\n${"─".repeat(70)}`);
141	  console.log(`[Step 1] 연구원의 초기 관점`);
142	  console.log(`${"─".repeat(70)}`);
143	
144	  const initialView = `AI 기술은 빠르게 발전하고 있습니다. 특히 생성형 AI의 발전으로 많은 산업에서
145	혁신이 일어나고 있습니다. 다만 규제와 윤리 문제도 동시에 고려해야 합니다.`;
146	
147	  console.log(`\n🔵 Researcher:\n${initialView}\n`);
148	  researcher.messageHistory.push({
149	    received: null,
150	    response: initialView
151	  });
152	
153	  // Step 2: 비평가가 비판 제시
154	  console.log(`\n${"─".repeat(70)}`);
155	  console.log(`[Step 2] 비평가의 검토`);
156	  console.log(`${"─".repeat(70)}`);
157	
158	  await researcher.sendMessage("critic", initialView);
159	  await new Promise(resolve => setTimeout(resolve, 1000));
160	
161	  const criticResponse = await critic.processInbox();
162	  console.log(`\n🔴 Critic:\n${criticResponse}\n`);
163	
164	  // Step 3: 종합가가 통합 의견 제시
165	  console.log(`\n${"─".repeat(70)}`);
166	  console.log(`[Step 3] 종합가의 최종 결론`);
167	  console.log(`${"─".repeat(70)}`);
168	
169	  const combinedInput = `
170	초기 의견:
171	"${initialView}"
172	
173	비평:
174	"${criticResponse}"
175	
176	이 두 관점을 종합하여 균형잡힌 결론을 제시해주세요.`;
177	
178	  await researcher.sendMessage("synthesizer", combinedInput);
179	  await new Promise(resolve => setTimeout(resolve, 1000));
180	
181	  const finalConclusion = await synthesizer.processInbox();
182	  console.log(`\n🟢 Synthesizer:\n${finalConclusion}\n`);
183	
184	  // Step 4: 결과 정리
185	  console.log(`\n${"=".repeat(70)}`);
186	  console.log(`📊 협업 결과 요약`);
187	  console.log(`${"=".repeat(70)}\n`);
188	
189	  console.log(`✅ 전송된 메시지: ${bus.messageLog.length}개`);
190	  console.log(`✅ 활성 에이전트: 3개`);
191	  console.log(`✅ 완료된 상호작용: 2개\n`);
192	
193	  console.log(`메시지 로그:`);
194	  bus.getLog().forEach((log, idx) => {
195	    console.log(`  ${idx + 1}. [${log.from}] → [${log.to}]`);
196	  });
197	}
198	
199	// ============= 실시간 토론 (더 복잡한 예제) =============
200	async function realtimeDebate() {
201	  console.log(`\n${"=".repeat(70)}`);
202	  console.log(`💬 실시간 멀티 Claude 토론`);
203	  console.log(`${"=".repeat(70)}\n`);
204	
205	  const bus = new MessageBus();
206	  const agentA = new ClaudeAgent("agentA", "researcher", bus);
207	  const agentB = new ClaudeAgent("agentB", "critic", bus);
208	
209	  const topic = "원격 근무는 생산성을 높이는가?";
210	
211	  // Agent A의 주장
212	  console.log(`\n[Round 1] Agent A의 주장`);
213	  const argumentA = `원격 근무는 통근 시간을 절약하고, 개발자들이 더 집중할 수 있는 환경을
214	제공합니다. 실제 많은 기업들이 원격 근무 도입 후 생산성 향상을 보고했습니다.`;
215	  console.log(`🟦 Agent A:\n${argumentA}\n`);
216	  agentA.messageHistory.push({ received: null, response: argumentA });
217	
218	  // Agent B의 반박
219	  await agentA.sendMessage("agentB", argumentA);
220	  await new Promise(resolve => setTimeout(resolve, 1000));
221	
222	  console.log(`\n[Round 2] Agent B의 반박`);
223	  const rebuttal = await agentB.processInbox();
224	  console.log(`🟥 Agent B:\n${rebuttal}\n`);
225	
226	  // Agent A의 재반박
227	  await agentB.sendMessage("agentA", rebuttal);
228	  await new Promise(resolve => setTimeout(resolve, 1000));
229	
230	  console.log(`\n[Round 3] Agent A의 재반박`);
231	  const counter = await agentA.processInbox();
232	  console.log(`🟦 Agent A:\n${counter}\n`);
233	
234	  console.log(`\n✅ 토론 완료! (총 3라운드)\n`);
235	}
236	
237	// ============= 메인 =============
238	async function main() {
239	  try {
240	    // 협업 워크플로우
241	    await collaborativeWorkflow();
242	
243	    // 실시간 토론
244	    await realtimeDebate();
245	
246	    console.log(`\n${"=".repeat(70)}`);
247	    console.log(`✨ 모든 에이전트 상호작용 완료`);
248	    console.log(`${"=".repeat(70)}\n`);
249	  } catch (error) {
250	    console.error("❌ 에러:", error.message);
251	    process.exit(1);
252	  }
253	}
254	
255	main();
